// #59019b מסך מידע להתאמת מכרזים — шаг 2 мастера /onboarding, роль ADMIN компании «QA Test בע"מ».
// @data: шаг мастера и данные профиля — общие для аккаунта; после каждого теста мастер возвращается на шаг 4.
import { test, expect, Page } from '@playwright/test';
import { authState, openWizardStep, qaFile, qaName, restoreWizard, stepTitle, uploadItem } from '../helpers/tenderflow';

const FIX_BANNER = 'יש להשלים או לתקן את השדות המסומנים כדי להמשיך.';
const turnoverGroup = (page: Page) => page.getByRole('group', { name: 'מחזור הכנסות שנתי (₪)' });

test.describe('מסך מידע להתאמת מכרזים', () => {
  test.describe.configure({ mode: 'serial' });
  test.use({ storageState: authState('admin') });
  test.afterEach(async ({ page }) => restoreWizard(page));

  test('המסך מציג את כל שדות המידע להתאמה והעלאת מסמכים #59019b @desktop @data', async ({ page }) => {
    await openWizardStep(page, 2);

    // דרישות 1–10
    for (const label of [
      'תחומי עיסוק *',
      'אזורי פעילות *',
      'ותק — מספר שנות פעילות',
      'ניסיון החברה',
      'פרויקטים ועבודות קודמות',
      'לקוחות וגופים שעבורם בוצעו עבודות',
      'רישיונות',
      'סיווגים מקצועיים',
      'תקנים',
      'אישורים רלוונטיים',
      'היקף מכרז מינימלי (₪)',
    ]) {
      await expect(page.getByLabel(label, { exact: true }), label).toBeVisible();
    }
    // מחזורי הכנסות — по годам, поля «שנת YYYY»
    await expect(turnoverGroup(page)).toBeVisible();
    await expect(turnoverGroup(page).getByLabel(/^שנת \d{4}$/).first()).toBeVisible();
    // Загрузка документов на экране (компонент #81a5e9)
    await expect(page.getByLabel('מסמכים ותעודות תומכים', { exact: true })).toBeAttached();
  });

  test('מחזור לא מספרי נדחה עם הודעת שגיאה מוטמעת #59019b @desktop @data', async ({ page }) => {
    await openWizardStep(page, 2);
    const turnover = turnoverGroup(page).getByRole('textbox').first();
    const original = await turnover.inputValue();

    // דרישות 14–15: только числа; некорректное значение — inline-ошибка, переход не выполняется
    for (const bad of ['abc', 'אבג', '12a', '!@#', '-5']) {
      await turnover.fill(bad);
      await page.getByRole('button', { name: 'הבא', exact: true }).click();
      await expect(stepTitle(page)).toHaveText('שלב 2 מתוך 4: מידע להתאמת מכרזים');
      await expect(turnover).toHaveAttribute('aria-invalid', 'true');
      await expect(page.getByText('יש להזין סכום בספרות בלבד').first()).toBeVisible();
      await expect(page.getByText(FIX_BANNER)).toBeVisible();
    }

    // Ошибка исчезает после исправления значения
    await turnover.fill('1000000');
    await expect(turnover).not.toHaveAttribute('aria-invalid', 'true');

    // Некорректное значение не сохранилось
    await page.reload();
    await openWizardStep(page, 2);
    await expect(turnoverGroup(page).getByRole('textbox').first()).toHaveValue(original);
  });

  test('ותק לא מספרי ושדות חובה ריקים נדחים עם הודעה #59019b @desktop @data', async ({ page }) => {
    await openWizardStep(page, 2);
    const years = page.getByLabel('ותק — מספר שנות פעילות', { exact: true });
    const fields = page.getByLabel('תחומי עיסוק *', { exact: true });
    const regions = page.getByLabel('אזורי פעילות *', { exact: true });
    const original = { years: await years.inputValue(), fields: await fields.inputValue(), regions: await regions.inputValue() };

    await years.fill('עשר');
    await fields.fill('');
    await regions.fill('');
    await page.getByRole('button', { name: 'הבא', exact: true }).click();

    // AC3 тикета: обязательные пустые / некорректные поля отклоняются с сообщением
    await expect(stepTitle(page)).toHaveText('שלב 2 מתוך 4: מידע להתאמת מכרזים');
    await expect(page.getByText('יש להזין מספר שנים בספרות בלבד')).toBeVisible();
    await expect(page.getByText('יש לציין תחומי עיסוק')).toBeVisible();
    await expect(page.getByText('יש לציין אזורי פעילות')).toBeVisible();
    await expect(page.getByText(FIX_BANNER)).toBeVisible();

    // Ничего не сохранилось
    await page.reload();
    await openWizardStep(page, 2);
    await expect(years).toHaveValue(original.years);
    await expect(fields).toHaveValue(original.fields);
    await expect(regions).toHaveValue(original.regions);
  });

  test('המידע נשמר לפרופיל ומוצג בכניסה חוזרת #59019b @desktop @data', async ({ page }) => {
    await openWizardStep(page, 2);
    const standards = page.getByLabel('תקנים', { exact: true });
    const original = await standards.inputValue();
    const line = qaName('omi-standard');

    try {
      await standards.fill(original ? `${original}\n${line}` : line);
      await page.getByRole('button', { name: 'הבא', exact: true }).click();

      // דרישות 16–17: сохранение и переход к следующему шагу
      await expect(stepTitle(page)).toHaveText('שלב 3 מתוך 4: גורמים מקצועיים קבועים');

      // דרישה 13 / AC2: заполненное состояние при возврате и после перезагрузки (многострочное значение целиком)
      await page.getByRole('button', { name: 'הקודם', exact: true }).click();
      await expect(stepTitle(page)).toHaveText('שלב 2 מתוך 4: מידע להתאמת מכרזים');
      await expect(standards).toHaveValue(original ? `${original}\n${line}` : line);

      await page.reload();
      await openWizardStep(page, 2);
      await expect(standards).toHaveValue(original ? `${original}\n${line}` : line);
    } finally {
      // Очистка: вернуть исходное значение
      await openWizardStep(page, 2);
      await standards.fill(original);
      await page.getByRole('button', { name: 'הבא', exact: true }).click();
      await expect(stepTitle(page)).toContainText('שלב 3 מתוך 4');
    }
  });

  test('העלאת מסמכים תומכים: שני קבצים, דחיית exe, שמירה לאחר רענון והסרה #59019b @desktop @data', async ({ page }) => {
    await openWizardStep(page, 2);
    const input = page.getByLabel('מסמכים ותעודות תומכים', { exact: true });
    const base = qaName('omi-doc');
    const files = [qaFile(`${base}-1`, 'pdf'), qaFile(`${base}-2`, 'png')];
    const exe = qaFile(`${base}-bad`, 'exe');

    try {
      // דרישה 10: загрузка документов на экране
      await input.setInputFiles(files);
      for (const f of files) await expect(uploadItem(page, f.name).getByRole('status')).toHaveText('הועלה');

      await input.setInputFiles(exe);
      await expect(page.getByRole('alert').filter({ hasText: `סוג הקובץ ${exe.name} אינו נתמך` })).toBeVisible();
      await expect(uploadItem(page, exe.name)).toHaveCount(0);

      await page.reload();
      await openWizardStep(page, 2);
      for (const f of files) await expect(uploadItem(page, f.name)).toBeVisible();

      for (const f of files) {
        await page.getByRole('button', { name: `הסרה: ${f.name}` }).click();
        await expect(uploadItem(page, f.name)).toHaveCount(0);
      }
      await page.reload();
      await openWizardStep(page, 2);
      await expect(page.getByLabel('מסמכים ותעודות תומכים', { exact: true })).toBeAttached();
      for (const f of files) await expect(uploadItem(page, f.name)).toHaveCount(0);
    } finally {
      for (const f of files) {
        const btn = page.getByRole('button', { name: `הסרה: ${f.name}` });
        if (await btn.count()) await btn.click();
      }
    }
  });
});

test.describe('מסך מידע להתאמת מכרזים — הרשאות', () => {
  test.use({ storageState: authState('user') });

  test('משתמש רגיל אינו יכול לערוך את המסך #59019b @desktop @prod-safe', async ({ page }) => {
    await page.goto('/onboarding');
    // AC5 тикета: USER (משתמש רגיל) не получает доступ к мастеру профиля
    await expect(page.getByText('המסך זמין למנהלי חשבון בלבד.')).toBeVisible();
    await expect(stepTitle(page)).toHaveCount(0);
    await expect(page.getByLabel('תחומי עיסוק *', { exact: true })).toHaveCount(0);
  });
});
